    <section className="panel"><SectionTitle kicker="COMPETITOR RATES BY DAY" title="Giá đối thủ theo ngày" description="So sánh nhanh các hạng phòng tương đương trong 7 ngày tới." action={<select className="period-select"><option>7 ngày tới</option><option>30 ngày tới</option><option>Tháng 11</option></select>} /><DataTable headers={["NGÀY", "STANDARD", "DELUXE", "SUITE", "THỊ TRƯỜNG", "GỢI Ý"]} rows={[["08/11 · T4", "850.000 đ", "1.150.000 đ", "2.000.000 đ", <span className="status-tag gray-tag">Ổn định</span>, "Giữ giá"],["09/11 · T5", "880.000 đ", "1.220.000 đ", "2.100.000 đ", <span className="status-tag green-tag">Tăng nhẹ</span>, "+3–5%"],["10/11 · T6", "950.000 đ", "1.350.000 đ", "2.300.000 đ", <span className="status-tag amber-tag">Nhu cầu cao</span>, "Bảo vệ giá"],["11/11 · T7", "980.000 đ", "1.420.000 đ", "2.500.000 đ", <span className="status-tag amber-tag">Cao điểm</span>, "+8%"]]} /></section>
