function WhatIfDashboard() {
  const [price, setPrice] = useState(8);
  const [discount, setDiscount] = useState(0);
  const [capacity, setCapacity] = useState(80);
  const [saved, setSaved] = useState(false);
  const revenue = (90 + price * 0.6 - discount * 0.25 + (capacity - 80) * 0.12).toFixed(1);
  const occupancy = Math.max(48, Math.min(98, 75 - price * 0.35 + discount * 0.55 + (capacity - 80) * 0.12)).toFixed(0);
  return <>
    <PageHeader eyebrow="WHAT-IF SIMULATOR" title={<>Mô phỏng <em>What-if.</em></>} description="Thử các thay đổi về giá, ưu đãi và phân bổ công suất trước khi áp dụng vào thực tế." action={<Button onClick={() => setSaved(true)}>{saved ? "Đã lưu kịch bản ✓" : "Lưu kịch bản"}</Button>} />
    <section className="visual-banner whatif-hero"><img src="/images/anh-nen-khach-san.png" alt="Mô phỏng kịch bản doanh thu" /><div className="visual-banner-copy"><span className="visual-label">SCENARIO · TEST · DECIDE</span><h3>Thử trước khi thị trường trả lời.</h3><p>Thay đổi tham số và nhìn thấy tác động dự kiến lên doanh thu, công suất và lợi nhuận.</p><div className="visual-metric"><strong>+{price}%</strong><span>thay đổi giá đang xét</span></div></div></section>
    <section className="whatif-actions"><div><span className="section-kicker">KỊCH BẢN MỚI</span><strong>Điều chỉnh và chạy mô phỏng</strong></div><button onClick={() => { setPrice(8); setDiscount(0); setCapacity(80); }}>↺ Đặt lại</button><button onClick={() => setSaved(true)}>✓ Lưu kịch bản</button></section>
    <section className="whatif-layout"><section className="panel whatif-controls"><SectionTitle kicker="PARAMETERS" title="Chỉnh tham số" description="Kéo thanh điều chỉnh để tạo kịch bản mới." /><label className="whatif-range"><span>Thay đổi giá <b>{price > 0 ? "+" : ""}{price}%</b></span><input type="range" min="-15" max="20" value={price} onChange={(event) => setPrice(Number(event.target.value))} /></label><label className="whatif-range"><span>Ưu đãi / giảm giá <b>{discount}%</b></span><input type="range" min="0" max="30" value={discount} onChange={(event) => setDiscount(Number(event.target.value))} /></label><label className="whatif-range"><span>Phân bổ công suất <b>{capacity}%</b></span><input type="range" min="50" max="100" value={capacity} onChange={(event) => setCapacity(Number(event.target.value))} /></label><div className="whatif-selects"><label>Sản phẩm<select><option>Deluxe Ocean View</option><option>Standard Garden</option><option>Tour đảo 1 ngày</option></select></label><label>Thời gian áp dụng<select><option>Cuối tuần 08–10/11</option><option>Toàn tháng 11</option><option>Ngày thấp điểm</option></select></label></div><button className="primary-button run-simulation" onClick={() => setSaved(false)}>▶ Chạy mô phỏng</button></section><section className="panel whatif-result"><SectionTitle kicker="EXPECTED RESULT" title="Kết quả dự kiến" description="Tác động của kịch bản hiện tại." /><div className="whatif-result-number">{revenue}<small>M</small><span>doanh thu / 7 ngày</span></div><div className="whatif-result-grid"><div><strong>{occupancy}%</strong><span>Công suất</span></div><div><strong>+{(price * .32 - discount * .18).toFixed(1)}%</strong><span>Lợi nhuận</span></div><div><strong>{price > 0 ? "+" : ""}{(price * .6 - discount * .25).toFixed(1)}M</strong><span>Tác động ròng</span></div></div><div className="whatif-compare"><span>Hiện tại <b>90M</b></span><i>→</i><span>Kịch bản <b>{revenue}M</b></span></div></section></section>
    <section className="panel"><SectionTitle kicker="SAVED SCENARIOS" title="Kịch bản gần đây" /><DataTable headers={["KỊCH BẢN", "THAY ĐỔI", "DOANH THU DỰ KIẾN", "CÔNG SUẤT", "TRẠNG THÁI"]} rows={[["Cuối tuần tháng 11", "+8% giá · 80% công suất", "94,8M", "72%", <span className="status-tag green-tag">Đã lưu</span>],["Kích cầu thứ tư", "Giảm 10% · Tặng bữa sáng", "78,4M", "86%", <span className="status-tag gray-tag">Bản nháp</span>],["Bảo vệ giá cao điểm", "+12% giá · Không ưu đãi", "96,2M", "68%", <span className="status-tag amber-tag">Chờ xem</span>]]} /></section>
  </>;
}

